{
  "root_causes": [
    {
      "service": "ts-config-service",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT 'abn' p, service_name, attr_k8s_pod_name pod, min(time)::VARCHAR first_t, max(time)::VARCHAR last_t, count(*) n FROM abnormal_metrics_sum WHERE metric='k8s.pod.uptime' AND service_name='ts-config-service' GROUP BY 1,2,3 UNION ALL SELECT 'norm', service_name, attr_k8s_pod_name, min(time)::VARCHAR, max(time)::VARCHAR, count(*) FROM normal_metrics_sum WHERE metric='k8s.pod.uptime' AND service_name='ts-config-service' GROUP BY 1,2,3",
          "claim": "Config pod reports uptime through the normal window but has no uptime rows at all in the abnormal window."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, count(*) n, min(time)::VARCHAR first_t, max(time)::VARCHAR last_t FROM abnormal_traces WHERE service_name='ts-config-service' GROUP BY 1",
          "claim": "Config-service emitted only 6 server spans in the abnormal window, first appearing about two minutes after the incident began."
        },
        {
          "kind": "trace",
          "sql": "SELECT time::VARCHAR ts, service_name, span_name, attr_span_kind kind, attr_status_code st, duration/1e6 ms, attr_http_response_status_code code FROM abnormal_traces WHERE service_name='ts-seat-service' AND attr_span_kind='Client' AND duration > 1e8 ORDER BY time",
          "claim": "Seat's outbound GET calls hang about 129 s and end in error with no response code."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-config-service",
      "to": "ts-seat-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) errs, approx_quantile(c.duration/1e6,0.95) callee_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.attr_span_kind='Server' AND p.attr_span_kind='Client' AND p.service_name='ts-seat-service' AND p.service_name<>c.service_name GROUP BY 1,2",
          "claim": "Seat's calls to config-service stall; seat's Client GET spans take about 129 s and fail, with no config child spans."
        }
      ]
    },
    {
      "from": "ts-seat-service",
      "to": "ts-travel2-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) errs, approx_quantile(c.duration/1e6,0.95) callee_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.attr_span_kind='Server' AND p.attr_span_kind='Client' AND p.service_name IN ('ts-travel2-service') AND c.service_name='ts-seat-service' GROUP BY 1,2",
          "claim": "Travel2's calls to seat return errors after about 129 s, one error out of one call."
        }
      ]
    },
    {
      "from": "ts-travel2-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) errs, approx_quantile(c.duration/1e6,0.95) callee_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.attr_span_kind='Server' AND p.attr_span_kind='Client' AND p.service_name='ts-route-plan-service' AND c.service_name='ts-travel2-service' GROUP BY 1,2",
          "claim": "Route-plan's calls to travel2 hit the stalled path: 2 of 4 errored, about 176 s p95 duration."
        }
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) errs, approx_quantile(c.duration/1e6,0.95) callee_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.attr_span_kind='Server' AND p.attr_span_kind='Client' AND p.service_name='ts-travel-plan-service' AND c.service_name='ts-route-plan-service' GROUP BY 1,2",
          "claim": "Travel-plan's calls to route-plan take about 174 s p95, with 3 of 11 erroring."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code st, approx_quantile(duration/1e6,0.95) p95_ms, count(*) n FROM abnormal_traces WHERE service_name='ts-ui-dashboard' GROUP BY 1,2,3 ORDER BY n DESC LIMIT 10",
          "claim": "User-facing dashboard requests show multi-second tails and 20 s maxima while travel-plan calls are slowed by the chain."
        }
      ]
    }
  ]
}
